-- Fuller bios written from each trainer's own website. Skips claimed listings.
begin;
update public.trainers set bio = 'Stanford Pilates is a Pilates and barre studio on Free School Lane in central Lincoln, with private and group classes for all abilities. Physiotherapy and sports massage appointments are also available in the same studio, for rehab and injury prevention.' where slug = 'stanford-pilates-lincoln' and claimed_by is null;
update public.trainers set bio = 'Kevin runs KCPT at Ladeside in Perth, offering one-to-one personal training and small-group PT. Small-group sessions give you a set session to follow and a coach to guide you, with the energy of training alongside other people.' where slug = 'kevin-cuthbert-pt' and claimed_by is null;
update public.trainers set bio = 'Ollie is a personal trainer based in the Ecclesall area of Sheffield, offering one-to-one personal training with a holistic approach. He works with people who want to lose weight, tone up or simply feel better, without giving up the rest of their life.' where slug = 'ollie-king-pt' and claimed_by is null;
update public.trainers set bio = 'The Movement Base is a reformer and mat Pilates studio in Leigh-on-Sea, with introductory sessions, group classes and private sessions. Teaching is adapted around each person''s history, such as an old injury or ongoing pain.' where slug = 'the-movement-base' and claimed_by is null;
update public.trainers set bio = 'ReFRAME Wellness Club in Sunderland is a reformer Pilates and Wunda Chair studio with small class sizes and attentive instruction, rooted in Joseph Pilates'' original method. It welcomes complete beginners as well as people with an established practice.' where slug = 'reframe-wellness-club' and claimed_by is null;
update public.trainers set bio = 'The Reformer Club is a boutique reformer Pilates studio in Tettenhall, Wolverhampton, running 50-minute group classes plus 1-1, 2-1 and small group sessions in contemporary Pilates. Classes range from Form and Flow to Jump and a Mother Club class, for all abilities.' where slug = 'the-reformer-club' and claimed_by is null;
update public.trainers set bio = 'Liz has run The Body Project in York since 2011, a boutique Pilates and personal training studio. It offers reformer Pilates classes, one-to-one and duet Pilates, and personal training sessions.' where slug = 'the-body-project-york' and claimed_by is null;
update public.trainers set bio = 'Transform Personal Training runs a private coaching studio in York, working mainly with adults in their 40s and 50s who want to lose weight, build strength and get their energy back. Clients get a clear plan, coach-led sessions and weekly accountability, from a team coaching for over 10 years.' where slug = 'transform-pt-york' and claimed_by is null;
update public.trainers set bio = 'Chloe teaches small, bespoke Pilates and Slings classes in Stoke Newington, plus private sessions and group classes on Zoom. Her classes suit people with ongoing back, hip or knee pain, low energy or a fear of movement, and those who want strength for everyday life.' where slug = 'chloe-pilates-stoke-newington' and claimed_by is null;
update public.trainers set bio = 'HomeHealth Pilates sends Pilates instructors to clients'' homes, workplaces and local parks across London and the South East, for private one-to-one sessions. New clients can start with two tester sessions.' where slug = 'home-health-pilates-london' and claimed_by is null;
update public.trainers set bio = 'Reece Mander Fitness has offered personal training in E14, Limehouse and Canary Wharf since 2014, mainly for working professionals. One-to-one coaching takes a holistic approach to weight loss and health, starting with a consultation.' where slug = 'reece-mander-fitness-canary-wharf' and claimed_by is null;
update public.trainers set bio = 'Aaron is a personal trainer with a BSc in Sport Science and nine years of experience, training clients across Portsmouth, Southsea, Gosport, Fareham and Waterlooville. He writes personalised programmes and also offers sports massage, and knows first-hand how training can rebuild confidence.' where slug = 'aaron-choi-pt-portsmouth' and claimed_by is null;
update public.trainers set bio = 'BOD Studios in Whitchurch Village, Cardiff, runs beginner-friendly reformer Pilates classes led by a physiotherapy team, alongside physiotherapy appointments. Classes focus on getting stronger, moving better and preventing injuries.' where slug = 'bod-studios-cardiff' and claimed_by is null;
update public.trainers set bio = 'Sarah Baker has taught Pilates for 12 years, and since 2018 at InsideOut Pilates in Derby city centre. She teaches both equipment sessions and mat classes for all levels, with extra guidance for complete beginners, plus one-to-one tuition.' where slug = 'inside-out-pilates-derby' and claimed_by is null;
update public.trainers set bio = 'Society is a reformer Pilates studio in Trentham, Stoke-on-Trent, running small classes designed to strengthen your body and improve posture, with a supportive instructor who keeps a close eye on beginners.' where slug = 'society-pilates-stoke' and claimed_by is null;
update public.trainers set bio = 'Pivot Therapies is a physiotherapy, Pilates and wellness studio in Stoke-on-Trent, led by a clinical lead physiotherapist. It builds personalised recovery plans and runs a timetable of Pilates for strength and posture and yoga for relaxation.' where slug = 'pivot-therapies-stoke' and claimed_by is null;
update public.trainers set bio = 'SRG Health & Fitness runs Thrive, a ladies-only small group personal training service in Bradford for women over 35 and 50+, focused on building strength, reducing aches and pains and growing confidence. Online coaching is also available.' where slug = 'srg-health-fitness-bradford' and claimed_by is null;
update public.trainers set bio = 'Chris O''Rourke runs COR Personal Fitness, a private gym on Low Hall Road in Horsforth, close to Calverley, Rodley and Rawdon. He and fellow trainer Callum offer one-to-one and small group sessions for general fitness, fat loss, strength and agility.' where slug = 'cor-personal-fitness-horsforth' and claimed_by is null;
update public.trainers set bio = 'Alive Fitness is a community fitness studio in Crosby offering group sessions and personal training, both one-to-one and two-to-one. People join for goals around how they look or a specific event, and the coaches support and encourage them along the way.' where slug = 'alive-fitness-crosby' and claimed_by is null;
update public.trainers set bio = 'Susie Ferry founded Inspired Pilates in Liverpool and has over 27 years of experience in health, rehabilitation and fitness. The studio runs short 20-minute Pilates classes for busy people, blending Pilates, yoga and mindful movement, with online classes and an app too.' where slug = 'inspired-pilates-liverpool' and claimed_by is null;
update public.trainers set bio = 'Andy Coyne runs Improve Personal Training from his own studio in Wavertree, covering Allerton, Mossley Hill, Aigburth, Childwall and the rest of South Liverpool. He helps with weight management, pre and postnatal exercise, health conditions, rowing strength and family fitness, with online sessions too.' where slug = 'improve-pt-wavertree' and claimed_by is null;
update public.trainers set bio = 'Reshape Infinity Fitness offers personal trainers in Liverpool city centre, with one-to-one sessions, a buddy system for training with up to two friends, group PT and home visits.' where slug = 'reshape-infinity-fitness-liverpool' and claimed_by is null;
update public.trainers set bio = 'Health by Science is a physio-led clinic and personal training studio on Giles Street, Leith. HCPC-registered physiotherapists, personal trainers and sports massage therapists work as one team, and most people start with a one-to-one Movement MOT to assess strength, mobility and any injury history.' where slug = 'health-by-science-edinburgh' and claimed_by is null;
update public.trainers set bio = 'Learn to Lift Training is based in Glasgow''s Southside, with a fully private personal training gym, group bootcamps and online coaching. The team has over 20 years of combined coaching experience and helps people lose fat, build muscle and grow in strength and confidence.' where slug = 'learn-to-lift-glasgow' and claimed_by is null;
update public.trainers set bio = 'Coconut Room is a reformer Pilates studio in Finnieston, Glasgow, mixing instructor-led classes with flexible on-demand reformer sessions you can book around your own schedule. Beginners and regulars are both welcome.' where slug = 'coconut-room-pilates' and claimed_by is null;
update public.trainers set bio = 'Pete is a personal trainer and nutrition coach with his own private studio in North Leeds (LS17). He writes both your training and your food plan, checks in weekly, and coaches 1-2-1 in the studio or online through his app, with a focus on beginners and people returning after years away.' where slug = 'pete-gawtry-fitness-leeds' and claimed_by is null;
update public.trainers set bio = 'Reform & Glow is a reformer Pilates studio in Wigston, Leicester, running small group and private Pilates classes in a calm, friendly setting. It welcomes people who are new to Pilates as well as regulars, with a focus on clear instruction and community.' where slug = 'reform-and-glow-leicester' and claimed_by is null;
update public.trainers set bio = 'Studio PLT is a reformer Pilates studio in Oadby, Leicester, running classes designed to build strength, improve mobility and help you de-stress and reset.' where slug = 'studio-plt-leicester' and claimed_by is null;
update public.trainers set bio = 'Alison runs an inclusive Pilates studio in Salisbury with small classes from beginner to advanced, on the mat, reformer, chair and ladder barrel. There are also Pilates barre classes and sessions for older adults, runners and pre and postnatal clients, plus one-to-one and small group sessions.' where slug = 'alison-pilates-salisbury' and claimed_by is null;
update public.trainers set bio = 'Ben founded Ben''s Pilates in Winchester after more than a decade in the Pilates and fitness industry, including coaching at London studios. The studio focuses on dynamic reformer Pilates, with daily group classes and tailored private sessions.' where slug = 'bens-pilates-winchester' and claimed_by is null;
update public.trainers set bio = 'Tony Sidhu offers private one-to-one personal training in Feltham (TW14), serving Hounslow, Whitton, Heathrow and nearby West London, plus online coaching. A competitive bodybuilder, he combines tailored training, nutrition and accountability for fat loss, muscle gain and confidence.' where slug = 'sidhu-fitness-hounslow' and claimed_by is null;
update public.trainers set bio = 'SimFit Studio opened in Meanwood, North Leeds, in January 2025, near Headingley and Roundhay. It runs bootcamps, transformation camps, Hyrox training, Boxfit, senior strength classes and personal training, for people at any starting point.' where slug = 'simfit-studio-leeds' and claimed_by is null;
update public.trainers set bio = 'Studio 44 runs reformer, mat and hot mat Pilates in Southsea and Chichester, in a warm and supportive space. Classes include Foundations, Intermediate, Mums & Bumps, 44 Strong and 44 Flex, with a range of instructors.' where slug = 'studio-44-pilates-southsea' and claimed_by is null;
update public.trainers set bio = 'James Darlington, The Conscious Bodybuilder, is a natural bodybuilder in his 50s who coaches people over 35, especially men in their 40s and 50s, at Renegade Gym on Penarth Road in Cardiff and online. His training is built on structured planning, consistency and progressive heavy lifting.' where slug = 'conscious-bodybuilder-cardiff' and claimed_by is null;
update public.trainers set bio = 'Kanoa Personal Training offers bespoke personal training and nutrition across Battersea, Clapham, Fulham and Westminster, working within local gyms, plus fitness classes in Dulwich and corporate wellness sessions. Trainers focus on good form and steady progression.' where slug = 'kanoa-pt-battersea' and claimed_by is null;
update public.trainers set bio = 'Luna Reform is a boutique reformer and tower Pilates studio at St Andrew''s Place in Cardiff city centre. Classes are capped at six people, with all-levels, women-only and tower sessions focused on core strength, posture and balance.' where slug = 'luna-reform-cardiff' and claimed_by is null;
update public.trainers set bio = 'fitandhappy has run female personal training and outdoor boot camps for women in Edinburgh since 2016. Its female trainers focus on women''s health and fitness, from the pelvic floor and perimenopause to weight loss, alongside exercise and nutrition coaching.' where slug = 'fitandhappy-edinburgh' and claimed_by is null;
update public.trainers set bio = 'Pilates 4 All is a studio in Portobello, Edinburgh, offering small group reformer and mat Pilates, semi-private sessions, yoga, barre and infrared classes. Teaching blends classical and contemporary Pilates for all ages and abilities.' where slug = 'pilates-4-all-edinburgh' and claimed_by is null;
commit;

